type StopInput = Partial<GuideStop> & {
  id: string;
  name: string;
  coordinates: [number, number];
  description: string;
  primaryUrl: string;
  sourcePhoto: string;
  currentStatusUrl?: string;
  mapQuery?: string;
  editorialUrls?: string[];
};

function stop(input: StopInput): GuideStop {
  const {
    id,
    name,
    coordinates,
    description,
    primaryUrl,
    sourcePhoto,
    currentStatusUrl,
    mapQuery,
    editorialUrls = [],
    bookingUrl,
    ...rest
  } = input;
  const mapUrl = maps(mapQuery ?? `${name} Kuala Lumpur Malaysia`);
  return {
    id,
    poiId: `kuala-lumpur-venue-${id.replace(/^kl-/, "")}`,
    name,
    coordinates,
    description,
    photo: sourcePhoto,
    imageSourceUrl: sourcePhoto,
    imageSourceName: sourcePhoto.includes("wikimedia.org") || sourcePhoto.includes("commons.wikimedia.org")
      ? "Wikimedia Commons"
      : "Official venue, property, booking, or cited editorial media",
    sourceUrls: [...new Set([primaryUrl, currentStatusUrl, mapUrl, sourcePhoto, ...editorialUrls].filter(Boolean) as string[])],
    sourceEvidence: {
      officialUrl: primaryUrl,
      mapUrl,
      currentStatusUrl: currentStatusUrl ?? mapUrl,
      imageSourceUrl: sourcePhoto,
      editorialUrls,
      checkedAt,
      notes:
        "The official venue, property, museum, ticketing, or booking schedule was checked with a current map or operating-status source on 23 July 2026. Hours reproduce the published schedule and identify any calendar, holiday, prayer, booking, or event dependency.",
    },
    officialUrl: primaryUrl,
    ...(bookingUrl ? { bookingUrl } : {}),
    ...rest,
  };
}

